def uber_subject_py_outputs(params: UberSubjectPy, execution: Execution) -> UberSubjectPyOutputs:
    """Build the UberSubjectPyOutputs object for this tool."""
    root_v: OutputPathType = execution.output_file(".")
    return UberSubjectPyOutputs(
        root=root_v,
    )

def uber_subject_py_execute(params: UberSubjectPy, runner: Runner | None = None) -> UberSubjectPyOutputs:
    """
    uber_subject.py

    Graphical interface to afni_proc.py

    Author: AFNI Developers

    URL: https://afni.nimh.nih.gov/

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    uber_subject_py_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(UBER_SUBJECT_PY_METADATA)
    execution.params(params)
    args = uber_subject_py_cargs(params, execution)
    out = uber_subject_py_outputs(params, execution)
    execution.run(args)
    return out

